test('a pass 06', () => assert.equal(6+1, 7));
test('a pass 07', () => assert.equal(7+1, 8));
test('a pass 08', () => assert.equal(8+1, 9));
test('a pass 09', () => assert.equal(9+1, 10));
test('z failure', () => assert.equal(2+2, 5, 'MINIFYCLI_NODE_ASSERTION'));
